"""Add-on entry point.

No provider request is made until a validated local profile exists.  This keeps
the bridge from guessing an undocumented provider API or ever invoking control.
"""

from __future__ import annotations

import json
import logging
import os
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .profile import ProfileError, load_profile

LOG = logging.getLogger("md_parking_bridge")


class State:
    def __init__(self) -> None:
        self.started_at = time.time()
        self.profile_error: str | None = None
        try:
            load_profile()
        except ProfileError as exc:
            self.profile_error = str(exc)

    def diagnostics(self) -> dict[str, object]:
        return {
            "read_only": True,
            "provider_profile": "ready" if self.profile_error is None else "not_ready",
            "restream": "not_started" if self.profile_error else "pending",
            "uptime_seconds": int(time.time() - self.started_at),
            "last_refresh": None,
            "last_failure": self.profile_error,
        }


def make_handler(state: State, api_token: str):
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:  # noqa: N802
            if self.path not in {"/health", "/diagnostics"}:
                self.send_error(HTTPStatus.NOT_FOUND)
                return
            if not api_token or self.headers.get("Authorization") != f"Bearer {api_token}":
                self.send_error(HTTPStatus.UNAUTHORIZED)
                return
            body = json.dumps(state.diagnostics()).encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            LOG.info("status_api %s", format % args)

    return Handler


def main() -> None:
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(name)s: %(message)s")
    token = os.environ.get("API_TOKEN", "")
    state = State()
    if state.profile_error:
        LOG.warning("provider profile is not ready: %s", state.profile_error)
    server = ThreadingHTTPServer(("0.0.0.0", 8099), make_handler(state, token))
    LOG.info("read-only status API listening on port 8099")
    server.serve_forever()


if __name__ == "__main__":
    main()
